      "mr": "वैधानिक आदेशानुसार जिल्हा प्राधिकरणाने या मुदतीत मंजुरी दिली पाहिजे किंवा नकार कळवला पाहिजे:",
      "gu": "વૈધાનિક આદેશ મુજબ જિલ્લા સત્તામંડળે આ સમયગાળામાં મંજૂરી આપવી અથવા અસ્વીકાર જણાવવો જરૂરી છે:",
      "kn": "ಶಾಸನಬದ್ಧ ನಿಯಮದ ಪ್ರಕಾರ ಜಿಲ್ಲಾ ಪ್ರಾಧಿಕಾರವು ಈ ಕೆಳಗಿನ ಅವಧಿಯಲ್ಲಿ ಮಂಜೂರಾತಿ ನೀಡಬೇಕು ಅಥವಾ ತಿರಸ್ಕಾರ ತಿಳಿಸಬೇಕು:",
