      "or": "ବିଧିବଦ୍ଧ ନିର୍ଦ୍ଦେଶ ଅନୁଯାୟୀ ଜିଲ୍ଲା ପ୍ରାଧିକରଣ ଏହି ସମୟ ମଧ୍ୟରେ ମଞ୍ଜୁରୀ ଦେବା କିମ୍ବା ପ୍ରତ୍ୟାଖ୍ୟାନ ଜଣାଇବା ଆବଶ୍ୟକ:",
