  "All sanctioned civil works must be physically completed and handed over within 1 year from sanction order date. Overdue works require immediate Collectorate review and contractor audit.": {
      "hi": "सभी स्वीकृत सिविल कार्यों को स्वीकृति आदेश की तारीख से 1 वर्ष के भीतर भौतिक रूप से पूर्ण कर हस्तांतरित किया जाना चाहिए। अतिदेय कार्यों के लिए तत्काल कलेक्ट्रेट समीक्षा और ठेकेदार ऑडिट आवश्यक है।",
      "te": "మంజూరైన అన్ని సివిల్ పనులను మంజూరు ఆర్డర్ తేదీ నుండి 1 సంవత్సరంలోపు పూర్తి చేసి అప్పగించాలి. గడువు ముగిసిన పనులపై తక్షణ కలెక్టరేట్ సమీక్ష మరియు కాంట్రాక్టర్ ఆడిట్ అవసరం.",
      "ta": "அங்கீகரிக்கப்பட்ட அனைத்து சிவில் பணிகளும் ஒப்புதல் ஆணை தேதியிலிருந்து 1 வருடத்திற்குள் முடிக்கப்பட்டு ஒப்படைக்கப்பட வேண்டும். தாமதமான பணிகளுக்கு உடனடி மாவட்ட ஆட்சியர் ஆய்வும் ஒப்பந்ததாரர் தணிக்கையும் தேவை.",
      "bn": "অনুমোদিত সমস্ত নির্মাণ কাজ অনুমোদন আদেশের তারিখ থেকে ১ বছরের মধ্যে সম্পন্ন ও হস্তান্তর করতে হবে। মেয়াদোত্তীর্ণ কাজের জন্য অবিলম্বে কালেক্টরেট পর্যালোচনা ও ঠিকাদার নিরীক্ষা প্রয়োজন।",
      "mr": "मंजूर केलेली सर्व स्थापत्य कामे मंजुरीच्या तारखेपासून १ वर्षाच्या आत पूर्ण करून हस्तांतरित केली पाहिजेत. थकीत कामांसाठी तातडीने जिल्हाधिकारी आढावा आणि कंत्राटदार ऑडिट आवश्यक आहे.",
      "gu": "તમામ મંજૂર સિવિલ કાર્યો મંજૂરી આદેશ તારીખથી ૧ વર્ષની અંદર ભૌતિક રીતે પૂર્ણ કરી સોંપવા આવશ્યક છે. મુદત વીતી ગયેલા કાર્યો માટે કલેક્ટર સમીક્ષા અને કોન્ટ્રાક્ટર ઓડિટ જરૂરી છે.",
      "kn": "ಮಂಜೂರಾದ ಎಲ್ಲಾ ಕಾಮಗಾರಿಗಳನ್ನು ಮಂಜೂರಾತಿ ದಿನಾಂಕದಿಂದ 1 ವರ್ಷದೊಳಗೆ ಪೂರ್ಣಗೊಳಿಸಿ ಹಸ್ತಾಂತರಿಸಬೇಕು. ವಿಳಂಬವಾದ ಕಾಮಗಾರಿಗಳಿಗೆ ಜಿಲ್ಲಾಧಿಕಾರಿಗಳ ಪರಿಶೀಲನೆ ಮತ್ತು ಗುತ್ತಿಗೆದಾರರ ಲೆಕ್ಕಪರಿಶೋಧನೆ ಅಗತ್ಯ.",
      "ml": "അനുവദിച്ച എല്ലാ സിവിൽ പ്രവൃത്തികളും ഉത്തരവ് തീയതി മുതൽ 1 വർഷത്തിനുള്ളിൽ പൂർത്തിയാക്കി കൈമാറണം. കാലാവധി കഴിഞ്ഞ പ്രവൃത്തികൾക്ക് കളക്ടറേറ്റ് അവലോകനവും കരാറുകാരന്റെ ഓഡിറ്റും അടിയന്തിരമാണ്.",
      "pa": "ਸਾਰੇ ਮਨਜ਼ੂਰਸ਼ੁਦਾ ਸਿਵਲ ਕੰਮ ਮਨਜ਼ੂਰੀ ਹੁਕਮ ਦੀ ਮਿਤੀ ਤੋਂ 1 ਸਾਲ ਦੇ ਅੰਦਰ ਮੁਕੰਮਲ ਕਰਕੇ ਸੌਂਪੇ ਜਾਣੇ ਚਾਹੀਦੇ ਹਨ। ਬਕਾਇਆ ਕੰਮਾਂ ਲਈ ਤੁਰੰਤ ਕਲੈਕਟਰੇਟ ਸਮੀਖਿਆ ਅਤੇ ਠੇਕੇਦਾਰ ਆਡਿਟ ਜ਼ਰੂਰੀ ਹੈ।",
      "or": "ସମସ୍ତ ମଞ୍ଜୁରପ୍ରାପ୍ତ ନିର୍ମାଣ କାର୍ଯ୍ୟ ମଞ୍ଜୁରୀ ଆଦେଶ ତାରିଖରୁ ୧ ବର୍ଷ ମଧ୍ୟରେ ସମ୍ପୂର୍ଣ୍ଣ ହୋଇ ହସ୍ତାନ୍ତର ହେବା ଆବଶ୍ୟକ। ବିଳମ୍ବିତ କାର୍ଯ୍ୟ ପାଇଁ ତୁରନ୍ତ କଲେକ୍ଟରେଟ୍ ସମୀକ୍ଷା ଆବଶ୍ୟକ।",
      "ur": "تمام منظور شدہ تعمیراتی کام منظوری کے حکم کی تاریخ سے 1 سال کے اندر مکمل اور حوالے کیے جانے چاہئیں۔ تاخیر کا شکار کاموں کے لیے فوری کلکٹریٹ جائزہ اور ٹھیکیدار کا آڈٹ درکار ہے۔"
  },
