      "ml": "ഇരട്ട ഫണ്ട് അനുവദിക്കുന്നത് തടയാൻ പാർലമെന്ററി കാലാവധികളിലും സമാനമായ സ്ഥലങ്ങളിലും ഉള്ള പ്രവൃത്തികളെ സെമാന്റിക് ക്ലസ്റ്ററിംഗ് കണ്ടെത്തുന്നു.",
      "pa": "ਦੋਹਰੇ ਫੰਡਾਂ ਦੀ ਵੰਡ ਨੂੰ ਰੋਕਣ ਲਈ ਸਿਮੈਂਟਿਕ ਕਲੱਸਟਰਿੰਗ ਸੰਸਦੀ ਕਾਰਜਕਾਲਾਂ ਅਤੇ ਇਕੋ ਜਿਹੇ ਪਿੰਡਾਂ ਦੇ ਕੋਆਰਡੀਨੇਟਸ ਵਿੱਚ ਓਵਰਲੈਪਿੰਗ ਤਜਵੀਜ਼ਾਂ ਦੀ ਪਛਾਣ ਕਰਦੀ ਹੈ।",
