  "Surveillance of candidate relationships, analytical text similarity evidence, and high suspicion cluster alerts requiring physical audit.": {
      "hi": "उम्मीदवार संबंधों, विश्लेषणात्मक पाठ समानता साक्ष्य, और भौतिक ऑडिट की आवश्यकता वाले उच्च संदेह क्लस्टर अलर्ट की निगरानी।",
      "te": "అభ్యర్థి సంబంధాలు, విశ్లేషణాత్మక పాఠ్య పోలిక ఆధారాలు మరియు భౌతిక ఆడిట్ అవసరమైన హెచ్చరికల పర్యవేక్షణ.",
      "ta": "வேட்பாளர் உறவுகள், பகுப்பாய்வு உரை ஒற்றுமை சான்றுகள் மற்றும் நேரடி தணிக்கை தேவைப்படும் எச்சரிக்கைகள் மீதான கண்காணிப்பு.",
      "bn": "প্রার্থী সম্পর্ক, বিশ্লেষণমূলক পাঠ্য মিলের প্রমাণ এবং শারীরিক নিরীক্ষা প্রয়োজন এমন উচ্চ সন্দেহের সতর্কতার নজরদারি।",
      "mr": "उमेदवार संबंध, विश्लेषणात्मक मजकूर साम्य पुरावे आणि प्रत्यक्ष ऑडिट आवश्यक असलेल्या संशयास्पद सूचनांची देखरेख.",
      "gu": "ઉમેદવાર સંબંધો, વિશ્લેષણાત્મક લખાણ સમાનતા પુરાવા અને ભૌતિક ઓડિટ જરૂરી હોય તેવી શંકાસ્પદ ચેતવણીઓની દેખરેખ.",
      "kn": "ಅಭ್ಯರ್ಥಿ ಸಂಬಂಧಗಳು, ಪಠ್ಯ ಹೋಲಿಕೆ ಸಾಕ್ಷ್ಯಗಳು ಮತ್ತು ಭೌತಿಕ ಆಡಿಟ್ ಅಗತ್ಯವಿರುವ ಎಚ್ಚರಿಕೆಗಳ ಮೇಲ್ವಿಚಾರಣೆ.",
      "ml": "സ്ഥാനാർത്ഥി ബന്ധങ്ങൾ, വാചക സാമ്യത തെളിവുകൾ, ഓഡിറ്റ് ആവശ്യമുള്ള മുന്നറിയിപ്പുകൾ എന്നിവയുടെ നിരീക്ഷണം.",
      "pa": "ਉਮੀਦਵਾਰੀ ਸੰਬੰਧਾਂ, ਪਾਠ ਸਮਾਨਤਾ ਦੇ ਸਬੂਤਾਂ ਅਤੇ ਭੌਤਿਕ ਆਡਿਟ ਦੀ ਲੋੜ ਵਾਲੇ ਸ਼ੱਕੀ ਅਲਰਟਾਂ ਦੀ ਨਿਗਰਾਨੀ।",
      "or": "ପ୍ରାର୍ଥୀ ସମ୍ପର୍କ, ବିଶ୍ଳେଷଣାତ୍ମକ ପାଠ୍ୟ ସମାନତା ପ୍ରମାଣ ଏବଂ ଭୌତିକ ଅଡିଟ୍ ଆବଶ୍ୟକ କରୁଥିବା ସତର୍କତାର ନିରୀକ୍ଷଣ।",
      "ur": "امیدوار کے تعلقات، متنی مشابہت کے شواہد اور جسمانی آڈٹ کے متقاضی مشکوک انتباہات کی نگرانی۔"
  },
