  "High-severity proposals flagged for duplicate overlap, cost anomaly, or delay deviations requiring Collector decision.": {
      "hi": "दोहरे अतिव्यापन, लागत विसंगति, या विलंब विचलन के लिए चिह्नित उच्च-गंभीरता प्रस्ताव जिनके लिए कलेक्टर के निर्णय की आवश्यकता है।",
      "te": "కలెక్టర్ నిర్ణయం అవసరమైన డూప్లికేట్ ఓవర్‌లాప్, వ్యయ వ్యత్యాసం లేదా జాప్యం కోసం గుర్తించబడిన తీవ్రమైన ప్రతిపాదనలు.",
      "ta": "ஆட்சியரின் முடிவு தேவைப்படும் நகல் ஒன்றிணைவு, செலவு முரண்பாடு அல்லது தாமதங்களுக்காக கொடியிடப்பட்ட தீவிர முன்மொழிவுகள்.",
      "bn": "কালেক্টরের সিদ্ধান্তের অপেক্ষায় দ্বৈত কাজের মিল, ব্যয় অসঙ্গতি বা বিলম্বের কারণে চিহ্নিত উচ্চ-গুরুত্বের প্রস্তাব।",
      "mr": "जिल्हाधिकाऱ्यांच्या निर्णयाची आवश्यकता असलेले दुहेरी आच्छादन, खर्च विसंगती किंवा विलंबासाठी चिन्हांकित केलेले गंभीर प्रस्ताव.",
      "gu": "કલેક્ટરના નિર્ણયની જરૂર હોય તેવા ડુપ્લિકેટ ઓવરલેપ, ખર્ચ વિસંગતતા અથવા વિલંબ માટે ચિહ્નિત ઉચ્ચ-તીવ્રતા દરખાસ્તો.",
      "kn": "ಜಿಲ್ಲಾಧಿಕಾರಿಗಳ ನಿರ್ಧಾರ ಅಗತ್ಯವಿರುವ ನಕಲು ಅತಿಕ್ರಮಣ, ವೆಚ್ಚದ ಅಸಂಗತತೆ ಅಥವಾ ವಿಳಂಬಕ್ಕಾಗಿ ಗುರುತಿಸಲಾದ ಗಂಭೀರ ಪ್ರಸ್ತಾವನೆಗಳು.",
      "ml": "കളക്ടറുടെ തീരുമാനം ആവശ്യമുള്ള ഇരട്ടിപ്പ്, ചെലവ് വ്യതിയാനം, കാലതാമസം എന്നിവയ്ക്കായി അടയാളപ്പെടുത്തിയ നിർദ്ദേശങ്ങൾ.",
      "pa": "ਕਲੈਕਟਰ ਦੇ ਫੈਸਲੇ ਦੀ ਲੋੜ ਵਾਲੇ ਡੁਪਲੀਕੇਟ ਓਵਰਲੈਪ, ਲਾਗਤ ਵਿਗਾੜ, ਜਾਂ ਦੇਰੀ ਲਈ ਚਿੰਨ੍ਹਿਤ ਗੰਭੀਰ ਤਜਵੀਜ਼ਾਂ।",
      "or": "କଲେକ୍ଟରଙ୍କ ନିଷ୍ପତ୍ତି ଆବଶ୍ୟକ କରୁଥିବା ନକଲି ଅତିବ୍ୟାପ୍ତି, ଖର୍ଚ୍ଚ ଅସଙ୍ଗତି କିମ୍ବା ବିଳମ୍ବ ପାଇଁ ଚିହ୍ନିତ ଗୁରୁତର ପ୍ରସ୍ତାବ।",
      "ur": "کلکٹر کے فیصلے کے متقاضی ڈپلیکیٹ اوورلیپ، لاگت کی بے ضابطگی، یا تاخیر کی انحراف کے لیے نشان زد تجاویز۔"
  },
